package com.agriconnect.rescue;import java.util.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/rescue-points")class RescuePointController{private final JdbcClient db;RescuePointController(JdbcClient d){db=d;}@GetMapping List<Map<String,Object>>all(){return db.sql("select id,name,province,district,ward,address_detail as \"addressDetail\",status from rescue_points order by id").query().listOfRows();}@GetMapping("/{id}")Map<String,Object>one(@PathVariable long id){return db.sql("select id,name,province,district,ward,address_detail as \"addressDetail\",status from rescue_points where id=:id").param("id",id).query().listOfRows().stream().findFirst().orElseThrow(()->new DomainException(HttpStatus.NOT_FOUND,"RESCUE_POINT_NOT_FOUND","Rescue point not found"));}@PostMapping @PreAuthorize("hasRole('ADMIN')")ResponseEntity<?>create(@RequestBody Map<String,Object>x){var r=db.sql("insert into rescue_points(name,province,district,ward,address_detail,status)values(:n,:p,:d,:w,:a,coalesce(:s,'ACTIVE'))returning id").param("n",x.get("name")).param("p",x.get("province")).param("d",x.get("district")).param("w",x.get("ward")).param("a",x.get("addressDetail")).param("s",x.get("status")).query().singleRow();return ResponseEntity.status(201).body(one(((Number)r.get("id")).longValue()));}@RequestMapping(value="/{id}",method={RequestMethod.PUT,RequestMethod.PATCH})@PreAuthorize("hasRole('ADMIN')")Map<String,Object>update(@PathVariable long id,@RequestBody Map<String,Object>x){one(id);db.sql("update rescue_points set name=:n,province=:p,district=:d,ward=:w,address_detail=:a,status=:s,updated_at=now()where id=:id").param("n",x.get("name")).param("p",x.get("province")).param("d",x.get("district")).param("w",x.get("ward")).param("a",x.get("addressDetail")).param("s",x.getOrDefault("status","ACTIVE")).param("id",id).update();return one(id);}}
